-- NovaNoxX PRD v1.6 foundation. Later user decisions: fee 15%, EXCLUSIVE/MULTI.
-- Run on a new staging database first; this does not migrate existing SQLite data.
BEGIN;
CREATE TABLE users(id text PRIMARY KEY,email text NOT NULL,name text NOT NULL,salt text NOT NULL,hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX users_email_normalized ON users(lower(email));
CREATE TABLE identities(provider text NOT NULL,subject text NOT NULL,user_id text NOT NULL REFERENCES users(id),PRIMARY KEY(provider,subject));
CREATE TABLE sessions(token text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),expires bigint NOT NULL);
CREATE TABLE login_events(token text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),provider text NOT NULL,occurred bigint NOT NULL);
CREATE TABLE creator_profiles(user_id text PRIMARY KEY REFERENCES users(id),display_name text NOT NULL,bio text NOT NULL,country text NOT NULL,language text NOT NULL,portfolio text NOT NULL,updated bigint NOT NULL);
CREATE TABLE account_status(user_id text PRIMARY KEY REFERENCES users(id),plan text NOT NULL DEFAULT 'Free',neon_balance bigint NOT NULL DEFAULT 0 CHECK(neon_balance>=0));
CREATE TABLE creator_assets(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),metadata jsonb NOT NULL,status text NOT NULL CHECK(status IN ('DRAFT','REVIEW','ACTIVE','CHANGES_REQUESTED','REJECTED','PAUSED','RESERVED','SOLD')),sale_mode text NOT NULL CHECK(sale_mode IN ('EXCLUSIVE','MULTI')),created bigint NOT NULL,updated bigint NOT NULL);
CREATE TABLE creator_files(id text PRIMARY KEY,asset_id text NOT NULL REFERENCES creator_assets(id),user_id text NOT NULL REFERENCES users(id),kind text NOT NULL,name text NOT NULL,ext text NOT NULL,size bigint NOT NULL CHECK(size>=0),storage_key text NOT NULL UNIQUE,created bigint NOT NULL);
CREATE TABLE creator_avatars(user_id text PRIMARY KEY REFERENCES users(id),data bytea NOT NULL,mime text NOT NULL,updated bigint NOT NULL);
CREATE TABLE catalog_links(public_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,asset_id text NOT NULL UNIQUE REFERENCES creator_assets(id));
CREATE TABLE review_audit(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,asset_id text NOT NULL REFERENCES creator_assets(id),admin_id text NOT NULL REFERENCES users(id),decision text NOT NULL,occurred bigint NOT NULL);
CREATE TABLE creator_contract_records(id text PRIMARY KEY,asset_id text NOT NULL REFERENCES creator_assets(id),seller_id text NOT NULL REFERENCES users(id),metadata jsonb NOT NULL,submitted bigint NOT NULL);
CREATE TABLE briefs(id text PRIMARY KEY,buyer_id text NOT NULL REFERENCES users(id),status text NOT NULL,requirements jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE proposals(id text PRIMARY KEY,brief_id text NOT NULL REFERENCES briefs(id),creator_id text NOT NULL REFERENCES users(id),price_neon bigint NOT NULL CHECK(price_neon>0),terms jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders(id text PRIMARY KEY,buyer_id text NOT NULL REFERENCES users(id),seller_id text NOT NULL REFERENCES users(id),asset_id text REFERENCES creator_assets(id),brief_id text REFERENCES briefs(id),environment text NOT NULL CHECK(environment IN ('TEST','LIVE')),status text NOT NULL CHECK(status IN ('PENDING','PAID','IN_PROGRESS','PREVIEW_READY','COMPLETED','CANCELLED','REFUNDED')),price_neon bigint NOT NULL CHECK(price_neon>0),fee_bps integer NOT NULL DEFAULT 1500 CHECK(fee_bps BETWEEN 0 AND 10000),terms_snapshot jsonb NOT NULL,paid_at timestamptz,preview_at timestamptz,review_deadline timestamptz,review_paused_at timestamptz,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(asset_id,brief_id)=1),CHECK(buyer_id<>seller_id));
CREATE INDEX orders_buyer ON orders(buyer_id,created_at DESC);
CREATE INDEX orders_seller ON orders(seller_id,created_at DESC);
CREATE TABLE checkout_locks(asset_id text PRIMARY KEY REFERENCES creator_assets(id),buyer_id text NOT NULL REFERENCES users(id),order_id text NOT NULL REFERENCES orders(id),expires_at timestamptz NOT NULL);
CREATE TABLE order_events(id text PRIMARY KEY,order_id text NOT NULL REFERENCES orders(id),event_type text NOT NULL,actor_id text REFERENCES users(id),details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE order_messages(id text PRIMARY KEY,order_id text NOT NULL REFERENCES orders(id),sender_id text NOT NULL REFERENCES users(id),body text NOT NULL,attachments jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),order_id text REFERENCES orders(id),environment text NOT NULL CHECK(environment IN ('TEST','LIVE')),provider text NOT NULL,provider_payment_id text,request_key text NOT NULL UNIQUE,amount_krw bigint NOT NULL CHECK(amount_krw>0),status text NOT NULL CHECK(status IN ('PENDING','PAID','FAILED','PARTIALLY_REFUNDED','REFUNDED')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,environment,provider_payment_id));
CREATE TABLE refunds(id text PRIMARY KEY,payment_id text NOT NULL REFERENCES payments(id),order_id text REFERENCES orders(id),request_key text NOT NULL UNIQUE,amount_krw bigint NOT NULL CHECK(amount_krw>0),reason text NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallets(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),environment text NOT NULL CHECK(environment IN ('TEST','LIVE')),balance bigint NOT NULL DEFAULT 0 CHECK(balance>=0),UNIQUE(user_id,environment));
CREATE TABLE wallet_ledger(id text PRIMARY KEY,wallet_id text NOT NULL REFERENCES wallets(id),transaction_id text NOT NULL UNIQUE,order_id text REFERENCES orders(id),payment_id text REFERENCES payments(id),kind text NOT NULL CHECK(kind IN ('CHARGE','PURCHASE','REFUND','ADMIN_GRANT','ADMIN_DEDUCT','MIGRATION_OPENING')),delta bigint NOT NULL CHECK(delta<>0),balance_before bigint NOT NULL CHECK(balance_before>=0),balance_after bigint NOT NULL CHECK(balance_after>=0),actor_id text REFERENCES users(id),reason text NOT NULL,status text NOT NULL DEFAULT 'POSTED' CHECK(status='POSTED'),expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(balance_after=balance_before+delta),CHECK((kind IN ('CHARGE','REFUND','ADMIN_GRANT','MIGRATION_OPENING') AND delta>0) OR (kind IN ('PURCHASE','ADMIN_DEDUCT') AND delta<0)));
CREATE INDEX ledger_wallet_time ON wallet_ledger(wallet_id,created_at DESC);
CREATE TABLE settlements(id text PRIMARY KEY,order_id text NOT NULL UNIQUE REFERENCES orders(id),seller_id text NOT NULL REFERENCES users(id),gross_krw bigint NOT NULL CHECK(gross_krw>=0),fee_krw bigint NOT NULL CHECK(fee_krw>=0),other_fees_krw bigint NOT NULL DEFAULT 0 CHECK(other_fees_krw>=0),net_krw bigint NOT NULL CHECK(net_krw>=0),status text NOT NULL CHECK(status IN ('PENDING','ON_HOLD','READY','PAID','CANCELLED')),provider_reference text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(net_krw=gross_krw-fee_krw-other_fees_krw));
CREATE TABLE delivery_entitlements(order_id text NOT NULL REFERENCES orders(id),file_id text NOT NULL REFERENCES creator_files(id),buyer_id text NOT NULL REFERENCES users(id),granted_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz,PRIMARY KEY(order_id,file_id));
CREATE TABLE disputes(id text PRIMARY KEY,order_id text NOT NULL REFERENCES orders(id),reporter_id text NOT NULL REFERENCES users(id),kind text NOT NULL,status text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE subscriptions(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),plan text NOT NULL,status text NOT NULL,period_start timestamptz NOT NULL,period_end timestamptz NOT NULL,provider_reference text, CHECK(period_end>period_start));
CREATE TABLE subscription_events(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),subscription_id text REFERENCES subscriptions(id),kind text NOT NULL CHECK(kind IN ('TRIAL','UPGRADE','DOWNGRADE','CANCEL','RENEW')),details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE asset_price_history(id text PRIMARY KEY,asset_id text NOT NULL REFERENCES creator_assets(id),kind text NOT NULL CHECK(kind IN ('INITIAL','CURRENT','RECOMMENDED','PRODUCT_FIT','CREATIVE_FIT','SOLD')),price_neon bigint NOT NULL CHECK(price_neon>=0),actor_id text REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE asset_state_history(id text PRIMARY KEY,asset_id text NOT NULL REFERENCES creator_assets(id),state text NOT NULL,started_at timestamptz NOT NULL,ended_at timestamptz,CHECK(ended_at IS NULL OR ended_at>=started_at));
CREATE UNIQUE INDEX one_open_asset_state ON asset_state_history(asset_id) WHERE ended_at IS NULL;
CREATE TABLE favorites(user_id text NOT NULL REFERENCES users(id),asset_id text NOT NULL REFERENCES creator_assets(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,asset_id));
CREATE TABLE behavior_events(id text PRIMARY KEY,user_id text REFERENCES users(id),asset_id text REFERENCES creator_assets(id),kind text NOT NULL CHECK(kind IN ('IMPRESSION','VIEW','FAVORITE','CHECKOUT_STARTED','PURCHASE','BRIEF_CONVERSION')),details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE search_events(id text PRIMARY KEY,user_id text REFERENCES users(id),keyword text NOT NULL,result_count integer NOT NULL CHECK(result_count>=0),clicked_asset_id text REFERENCES creator_assets(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),order_id text REFERENCES orders(id),kind text NOT NULL,payload jsonb NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id text PRIMARY KEY,actor_id text REFERENCES users(id),action text NOT NULL,entity_type text NOT NULL,entity_id text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE contest_entries(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),title text NOT NULL,description text NOT NULL,creator text NOT NULL,ext text NOT NULL,size bigint NOT NULL,storage_key text NOT NULL,created bigint NOT NULL);
COMMIT;
